"의 바람의 가호!":"の風の加護！",
"전원이 적의 평타를 피하기 쉬워진다":"全員が敵の通常攻撃をかわしやすくなる",
"아군 전체 회피↑ 3턴":"味方全体 回避↑ 3ターン",
"쩍 — 얇은 얼음이 꺼졌다! 얼음물에 빠졌다가 기어 나왔다. (전원 HP 피해)":"バキッ — 薄い氷が割れた！ 氷水に落ちて、はい上がった。(全員HPダメージ)",
"작살과 검":"銛と剣",
"그 작살, 고기 잡던 거라며. 사람한테 겨눈 건 우리가 처음이야?":"その銛、魚を獲るやつなんだって？ 人に向けたのはオレたちが初めて？",
"사나":"サナ",
"처음이야. 마지막이면 좋겠고.":"初めて。最後だといいけど。",
"세던데. 팔이 아직 저려.":"強かったな。腕がまだしびれてるよ。",
"…고래는 한 번에 못 잡아. 숨이 찰 때까지 따라가는 거야. 너희한테도 그러려고 했어.":"…鯨は一度じゃ獲れない。息が切れるまで追うんだ。あんたたちにもそうするつもりだった。",
"그럼 저희는 숨이 덜 찬 고래였네요.":"では、わたしたちは息の切れていない鯨だったんですね。",
"웃기는 사람들이네. 그 빛을 켠 사람들이 이런 줄 몰랐어.":"おかしな連中。あの光を灯したのがこんな人たちだなんて知らなかった。",
"끄지 않는 불":"消さない火",
"군주는 등대를 안 끈대. 당연해. 삼백 해를 기다려서 겨우 켠 불이니까.":"君主は灯台を消さないって。当然だよ。三百年待って、やっと灯した火だから。",
"그 불 때문에 내 동생이 풀리고 있어도?":"その火のせいで、あたしの弟がほどけていても？",
"…그걸 모르겠어서 가는 거야. 우리 선조는 저편을 보지도 않고 문을 닫았어.":"…それが分からないから行くんだ。僕らの先祖は向こう側を見もせずに門を閉じた。",
"난 그 값을 삼백 해 치 봤어. 그러니까 이번엔, 보고 나서 정할 거야.":"僕はその代価を三百年分見た。だから今度は、見てから決める。",
"보고 나서도 안 끄겠다면?":"見たあとでも消さないと言ったら？",
"그땐 다른 길을 찾을 때까지 같이 있을게. 그건 약속할 수 있어.":"その時は別の道が見つかるまで一緒にいる。それは約束できるよ。",
"거둬 가는 것":"取り立てていくもの",
"선단에서 본 것… 멈춘 사람한테서 뭔가를 빼 가고 있었어요.":"船団で見たもの…止まった人から何かを抜き取っていました。",
"수집관의 일꾼들이야. 「풀리지 않게 돌보는 것」이라고 배웠어. 재상님 말씀으로.":"収集官の働き手だ。「ほどけないよう世話をする」と教わった。宰相様のお言葉で。",
"돌보는 놈들이 사냥개를 끌고 다녀?":"世話する奴らが猟犬を連れ歩くのか？",
"…나도 그게 걸려. 돌보는 거라면 왜 숨어서 하지.":"…あたしもそこが引っかかる。世話なら、なんで隠れてやるの。",
"재상이 누구야?":"宰相って誰？",
"칼릭 님. 별지기님 곁에서 삼백 해를 섬긴 분. 이 땅에서 그분을 의심하는 사람은 없어.":"カリク様。星守り様のそばで三百年仕えた方。あの地であの方を疑う人はいない。",
"삼백 해라. 그 숫자, 우린 좀 질렸는데.":"三百年ね。その数字、オレたちちょっと飽きてるんだけど。",
"살레나 항 동쪽 ▣ 얼어붙은 부두를 살펴보자":"サレナ港の東 ▣ 凍りついた埠頭を調べよう",
"부두 끝 ▣ 멈춘 등대섬에서 푸른 빛이 닿은 자리를 확인하자":"埠頭の先 ▣ 止まった灯台島で青い光が届いた場所を確かめよう",
